import{_ as a,o as t,c as o,ae as r}from"./chunks/framework.C4zpkcTP.js";const h=JSON.parse('{"title":"Approval workflow","description":"","frontmatter":{},"headers":[],"relativePath":"approvals.md","filePath":"approvals.md"}'),i={name:"approvals.md"};function l(n,e,d,s,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="approval-workflow" tabindex="-1">Approval workflow <a class="header-anchor" href="#approval-workflow" aria-label="Permalink to &quot;Approval workflow&quot;">​</a></h1><p>Destructive MCP actions do not execute directly. They create a pending human approval request that an administrator must decide.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>A destructive tool records a pending approval request that includes:</p><ul><li>the requesting credential,</li><li>the agent identity,</li><li>the tool,</li><li>the action type,</li><li>the target,</li><li>a written justification,</li><li>a one-hour expiry.</li></ul><p>The tool returns an approval identifier and a pending status. The action is not performed until an administrator approves it.</p><h2 id="deciding-an-approval" tabindex="-1">Deciding an approval <a class="header-anchor" href="#deciding-an-approval" aria-label="Permalink to &quot;Deciding an approval&quot;">​</a></h2><p>An administrator can approve or reject a pending approval through the admin API or dashboard.</p><p>Only on approval does DockPilot execute the action, inside a single database transaction that locks the approval row and writes the execution audit event.</p><p>Rejected, expired, and already-decided requests cannot execute anything. Approving a request whose target has disappeared results in a recorded <code>failed</code> approval instead of a silent success.</p><h2 id="executable-actions" tabindex="-1">Executable actions <a class="header-anchor" href="#executable-actions" aria-label="Permalink to &quot;Executable actions&quot;">​</a></h2><p>The executable action types are currently:</p><ul><li><code>session.revoke</code></li><li><code>ai_credential.revoke</code></li></ul><p>Any other action type is refused.</p><h2 id="good-defaults" tabindex="-1">Good defaults <a class="header-anchor" href="#good-defaults" aria-label="Permalink to &quot;Good defaults&quot;">​</a></h2><ul><li>Read-only tools never require approval.</li><li>Approval requests expire after one hour.</li><li>The approval record is auditable and tied to the requesting credential and agent identity.</li></ul>',16)])])}const v=a(i,[["render",l]]);export{h as __pageData,v as default};
